-- Jeu de LecteurDocumentsGed (« Documents », PROC_RECHERCHE_GED), lot 6 du plan-676a4b19 : les documents de la GED, chacun dans la
-- categorie que nomme sa reference (DocumentsGed.cs). Ce qui est range ou ecarte, et pourquoi : PROC_RECHERCHE_GED.attendu.
-- GED_RIG est creee par PROC_IMAGE.sql ; ses images et les PDF de PROC_PDF.sql entrent aussi dans cet ecran (« Sans référence »).
--
-- Les tables que nomment les categories (OPE_GED.cs:48-72). Aucune ligne n'est posee dans DEMANDE_EDITION ni dans FACTURE : la file
-- des editions (LecteurFileEditions) compte toutes les demandes d'edition, et les lots des factures liront FACTURE ; leurs
-- documents sont donc ici des ORPHELINS (leur reference ne les porte plus). DOCUMENT_DOSSIER et FACTURE sont creees plus loin par
-- PROC_XXAFF.sql : creees ici avant lui, a sa forme (memes colonnes NOT NULL), plus les colonnes lues par l'ecran.
IF OBJECT_ID(N'v2.GED_RIG') IS NULL
    CREATE TABLE v2.GED_RIG (GDRG_NUM_DOCUMENT varchar(40) NOT NULL PRIMARY KEY, GDRG_EXTENSION varchar(10) NOT NULL,
        GDRG_FICHIER varbinary(max) NULL, GDRG_FICHIER_PDF varbinary(max) NULL, GDRG_LOGIN_NT_ARCHIVAGE varchar(35) NOT NULL,
        GDRG_DATE_ARCHIVAGE datetime NOT NULL, GDRG_LOGIN_NT_EXTRACTION varchar(35) NULL, GDRG_DATE_EXTRACTION datetime NULL,
        GDRG_PATH_EXTRACTION varchar(2000) NULL, GDRG_REFERENCE varchar(200) NULL, GDRG_NOM_FICHIER varchar(160) NULL,
        GDRG_NB_PAGE int NULL);
IF OBJECT_ID(N'v2.ELEMENT_FUSION') IS NULL
    CREATE TABLE v2.ELEMENT_FUSION (ELMFS_ID_ELMFS int NOT NULL PRIMARY KEY, ELMFS_REFERENCE varchar(32) NOT NULL, ELMFS_NUM_DOCUMENT varchar(40) NOT NULL);
IF OBJECT_ID(N'v2.MAQUETTE') IS NULL
    CREATE TABLE v2.MAQUETTE (MQTT_CODE_MAQUETTE varchar(40) NOT NULL PRIMARY KEY, MQTT_NUM_DOCUMENT varchar(40) NULL, MQTT_TYPE_MAQUETTE varchar(30) NULL);
IF OBJECT_ID(N'v2.SIREN_EN_LIGNE') IS NULL
    CREATE TABLE v2.SIREN_EN_LIGNE (SIRLG_ID_SIRLG int NOT NULL PRIMARY KEY, SIRLG_NUM_LIAISON varchar(14) NOT NULL,
        SIRLG_GUID_XML_ENVOYE varchar(40) NULL, SIRLG_GUID_XML_RECU varchar(40) NULL);
IF OBJECT_ID(N'v2.DEMANDE_EDITION') IS NULL
    CREATE TABLE v2.DEMANDE_EDITION (DMNED_ID_DMNED int NOT NULL PRIMARY KEY, DMNED_LIBELLE_DOCUMENT varchar(255) NULL);
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_NUM_DOCUMENT_EDITION') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_NUM_DOCUMENT_EDITION varchar(40) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_NUM_DOCUMENT_FLUX') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_NUM_DOCUMENT_FLUX varchar(40) NULL;
IF OBJECT_ID(N'v2.FACTURE') IS NULL
    CREATE TABLE v2.FACTURE (FACTU_NUMERO_FACTURE varchar(25) NOT NULL PRIMARY KEY, FACTU_NUM_DEMANDE varchar(32) NOT NULL);
IF COL_LENGTH('v2.FACTURE', 'FACTU_NUMERO_GED_DONNEES_XML') IS NULL ALTER TABLE v2.FACTURE ADD FACTU_NUMERO_GED_DONNEES_XML varchar(40) NULL;
IF OBJECT_ID(N'v2.DOCUMENT_DOSSIER') IS NULL
    CREATE TABLE v2.DOCUMENT_DOSSIER (DCMDS_ID_DCMDS int NOT NULL PRIMARY KEY, DCMDS_VALEUR_ID_METIER int NULL);
IF COL_LENGTH('v2.DOCUMENT_DOSSIER', 'DCMDS_NUM_DOCUMENT_0') IS NULL ALTER TABLE v2.DOCUMENT_DOSSIER ADD DCMDS_NUM_DOCUMENT_0 varchar(40) NULL;
IF COL_LENGTH('v2.DOCUMENT_DOSSIER', 'DCMDS_NUM_DOCUMENT_1') IS NULL ALTER TABLE v2.DOCUMENT_DOSSIER ADD DCMDS_NUM_DOCUMENT_1 varchar(40) NULL;
IF COL_LENGTH('v2.DOCUMENT_DOSSIER', 'DCMDS_NUM_DOCUMENT_2') IS NULL ALTER TABLE v2.DOCUMENT_DOSSIER ADD DCMDS_NUM_DOCUMENT_2 varchar(40) NULL;
IF OBJECT_ID(N'v2.DECISION_JUDICIAIRE') IS NULL
    CREATE TABLE v2.DECISION_JUDICIAIRE (DCJDC_ID_DCJDC int NOT NULL PRIMARY KEY, DCJDC_ID_INSTN int NOT NULL);
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_TYPE_DECISION') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_TYPE_DECISION varchar(10) NULL;
IF OBJECT_ID(N'v2.INSTANCE') IS NULL
    CREATE TABLE v2.INSTANCE (INSTN_ID_INSTN int NOT NULL PRIMARY KEY, INSTN_NUM_ROLE varchar(11) NULL, INSTN_NOM_COURANT varchar(250) NULL);

